package com.google.gson.stream;

import com.google.gson.stream.JsonWriter;
import java.io.*;
import java.io.Closeable;
import java.io.Flushable;
import java.io.IOException;
import java.io.StringWriter;
import java.io.Writer;
import java.math.*;
import java.util.*;
import java.util.Locale;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertThrows;

public class JsonWriter_value_TriageGen0Test {

    private JsonWriter jsonWriter;
    private Writer writer;

    @Before
    public void init() {
        writer = new StringWriter();
        jsonWriter = new JsonWriter(writer);
    }

    @Test
    public void testValue() throws IOException {
        jsonWriter.value("Hello");
        assertEquals("{\"value\":\"Hello\"}", writer.toString());
    }

    @Test
    public void testValue_Null() throws IOException {
        jsonWriter.value(null);
        assertEquals("{\"value\":null}", writer.toString());
    }

    @Test
    public void testValue_EmptyString() throws IOException {
        jsonWriter.value("");
        assertEquals("{\"value\":\"\"}", writer.toString());
    }

    @Test
    public void testValue_NonString() throws IOException {
        assertThrows(IOException.class, () -> jsonWriter.value(123));
    }

    @Test
    public void testValue_NullValue() throws IOException {
        jsonWriter.nullValue();
        assertEquals("{\"value\":null}", writer.toString());
    }

    @Test
    public void testValue_Locale() throws IOException {
        Locale locale = Locale.getDefault();
        jsonWriter.value(locale);
        assertEquals("{\"value\":\"en_US\"}", writer.toString());
    }

    @Test
    public void testValue_Currency() throws IOException {
        java.util.Currency currency = java.util.Currency.getInstance("USD");
        jsonWriter.value(currency);
        assertEquals("{\"value\":\"USD\"}", writer.toString());
    }

    @Test
    public void testValue_Number() throws IOException {
        jsonWriter.value(123);
        assertEquals("{\"value\":123}", writer.toString());
    }

    @Test
    public void testValue_Decimal() throws IOException {
        jsonWriter.value(123.456);
        assertEquals("{\"value\":123.456}", writer.toString());
    }

    @Test
    public void testValue_Float() throws IOException {
        jsonWriter.value(123.456f);
        assertEquals("{\"value\":123.456}", writer.toString());
    }

    @Test
    public void testValue_Double() throws IOException {
        jsonWriter.value(123.456d);
        assertEquals("{\"value\":123.456}", writer.toString());
    }

    @Test
    public void testValue_Long() throws IOException {
        jsonWriter.value(123L);
        assertEquals("{\"value\":123}", writer.toString());
    }

    @Test
    public void testValue_Character() throws IOException {
        jsonWriter.value('a');
        assertEquals("{\"value\":\"a\"}", writer.toString());
    }

    @Test
    public void testValue_Boolean() throws IOException {
        jsonWriter.value(true);
        assertEquals("{\"value\":true}", writer.toString());
    }

    @Test
    public void testValue_Bool() throws IOException {
        jsonWriter.value(true);
        assertEquals("{\"value\":true}", writer.toString());
    }

    @Test
    public void testValue_BigInteger() throws IOException {
        java.math.BigInteger bigInteger = java.math.BigInteger.valueOf(123);
        jsonWriter.value(bigInteger);
        assertEquals("{\"value\":123}", writer.toString());
    }

    @Test
    public void testValue_BigDecimal() throws IOException {
        java.math.BigDecimal bigDecimal = java.math.BigDecimal.valueOf(123.456);
        jsonWriter.value(bigDecimal);
        assertEquals("{\"value\":123.456}", writer.toString());
    }

    @Test
    public void testValue_NullPointerException() throws IOException {
        assertThrows(IOException.class, () -> jsonWriter.value(null));
    }

    @Test
    public void testValue_NullPointerExceptionNull() throws IOException {
        assertThrows(IOException.class, () -> jsonWriter.value(null));
    }

}
